/* eslint-disable @typescript-eslint/no-explicit-any */
/** Declarative definition of every business module's screens. The generic components (components/ModuleKit.tsx) render lists, row actions,
 *  create forms and report views from this; every permission shown here is ALSO enforced by the backend (the UI only hides what you cannot use). */
import {
  Boxes, Briefcase, Calculator, ClipboardCheck, FlaskConical, Factory, Megaphone, PackageCheck, ShoppingCart, ShoppingBag, Wrench, BarChart3, Users, type LucideIcon,
} from "lucide-react";

export type Tone = "success" | "warning" | "danger" | "info" | "neutral";
export type Kind = "text" | "mono" | "money" | "number" | "badge" | "date" | "datetime" | "bool";
export type Col = { key: string; label: string; kind?: Kind };
export type RefKey = "items" | "rm" | "fg" | "suppliers" | "customers" | "warehouses" | "brands" | "users" | "equipment" | "leads" | "formulations" | "campaigns" | "ecomAccounts" | "boms" | "pos" | "documents";
export type Field = {
  name: string; label: string; type: "text" | "number" | "date" | "textarea" | "select" | "checkbox" | "ref" | "refs" | "lines" | "csv";
  required?: boolean; options?: string[]; ref?: RefKey; lines?: Field[]; help?: string; placeholder?: string; step?: string; default?: any; section?: string;
};
export type Row = Record<string, any>;
export type Action = {
  label: string; path?: (r: Row) => string; href?: (r: Row) => string; method?: "POST" | "PUT"; perm?: string; when?: (r: Row) => boolean;
  fields?: Field[]; body?: (r: Row, v: Row) => any; confirm?: string; idempotent?: boolean; danger?: boolean; versioned?: boolean; result?: "json";
};
export type Create = { label: string; perm: string; path: string; fields: Field[]; body?: (v: Row) => any; idempotent?: boolean; title?: string };
export type Param = { name: string; label: string; type: "date" | "text" | "select"; options?: string[]; required?: boolean; default?: string | "today" | "month_start" | "year_start" };
export type Screen = {
  id: string; label: string; description: string; perm: string;
  list?: { api: string; params?: Record<string, string>; itemsKey?: string; cols: Col[]; status?: { param?: string; options: string[] }; detail?: (r: Row) => string; actions?: Action[]; paged?: boolean };
  report?: { api: string; params?: Param[] };
  create?: Create;
};
export type Module = { id: string; label: string; icon: LucideIcon; description: string; dashboard?: { api: string; perm: string }; screens: Screen[] };

const today = () => new Date().toISOString().slice(0, 10);
export const defaultParam = (p: Param) => (p.default === "today" ? today() : p.default === "month_start" ? today().slice(0, 8) + "01" : p.default === "year_start" ? today().slice(0, 5) + "01-01" : p.default ?? "");
export const toneFor = (v: string): Tone => {
  const s = String(v).toUpperCase();
  if (["APPROVED", "ACTIVE", "RELEASED", "RELEASE", "DONE", "CLOSED", "DELIVERED", "PAID", "PASSED", "POSTED", "RECEIVED", "WON", "OPERATIONAL", "COMPLETED", "VERIFIED", "PUBLISHED", "MATCHED", "SO_CREATED", "DECIDED", "AWARDED", "ACCEPTED", "CONVERTED", "HEALTHY", "OK"].includes(s)) return "success";
  if (["REJECTED", "CANCELLED", "FAILED", "HOLD", "BREAKDOWN", "REJECT", "LOST", "FAILED_DELIVERY", "RTO", "EXCEPTION", "ERROR", "CRITICAL", "LATE", "OBSOLETE"].includes(s)) return "danger";
  if (["DRAFT", "PLANNED", "NEW", "PENDING", "UNMATCHED", "IGNORED", "NONE"].includes(s)) return "neutral";
  if (["IN_TRANSIT", "BOOKED", "ALLOCATED", "PACKED", "CONFIRMED", "QUARANTINE", "INFO"].includes(s)) return "info";
  return "warning";
};

const uid = () => Math.floor(Math.random() * 1e9);
const st = (...s: string[]) => (r: Row) => s.includes(r.status);
const lineItem = (extra: Field[] = []): Field => ({ name: "items", label: "Lines", type: "lines", required: true, lines: [{ name: "item_id", label: "Item", type: "ref", ref: "items", required: true }, { name: "qty", label: "Qty", type: "number", required: true, step: "any" }, ...extra] });

